/********************************************** 
 * 함수명 : fn_searchCode() 
 * 설명    : 기초자산, 분배금형태코드 불러오기
 ***********************************************/
scwin.fn_searchCode = function() {
    /*		
    03685	DIGITAL_SECU_ULY_CD							기초자산		
    03698	DIGITAL_SECU_DISTR_TP_CD			분배금형태코드		
    */

    var arrCid = [{
        cid: "DIGITAL_SECU_ULY_CD",
        cnm: "cmb_DIGITAL_SECU_ULY_CD"
    }, {
        cid: "DIGITAL_SECU_DISTR_TP_CD",
        cnm: "cmb_DIGITAL_SECU_DISTR_TP_CD"
    }, {
        cid: "TAX_TP_CD",
        cnm: "cmb_TAX_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='DIGITAL_SECU_ULY_CD','DIGITAL_SECU_DISTR_TP_CD','TAX_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                // 기초자산 "없음" 공백값 추가
                if (j == 1 && arrCid[i].cid == "DIGITAL_SECU_ULY_CD") {
                    strCbd = "^없음";
                }
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
                //alert(strCbd);

            }
        }
        objCod.CBData = strCbd;
    }
};




/********************************************** 
 * 함수명 : fn_CheckForm() 
 * 설명    : 필수값 체크
 ***********************************************/
scwin.fn_CheckForm = function() {
    // 필수값 
    //기초자산

    // 기초자산 종류를 입력하였을 경우, 기초자산명이 공백값이면 필수 
    // 기초자산 종류가 없을 경우 기초자산명 입력X
    if (($c.stf.getObjectValue(cmb_DIGITAL_SECU_ULY_CD) != "") && $c.stf.getObjectValue(txb_DIGITAL_SECU_ULY_NM) == "") {
        $c.win.alert("[기초자산] 명을 입력하세요.");
        txb_DIGITAL_SECU_ULY_NM.focus();
        return;
    }
    //신탁기관발행기관코드
    if (($c.stf.getObjectValue(txb_TRST_INST_ISUR_CD) != "") && (txb_TRST_CONTRT_PD_STRT_DD.getValue() == "")) {
        $c.win.alert("[신탁기관 계약기간] 시작일을 입력하세요.");
        txb_TRST_CONTRT_PD_STRT_DD.focus();
        return;
    }
    if ((txb_TRST_CONTRT_PD_STRT_DD.getValue() != '') && (txb_TRST_CONTRT_PD_END_DD.getValue() != '')) {
        if (txb_TRST_CONTRT_PD_STRT_DD.getValue() > txb_TRST_CONTRT_PD_END_DD.getValue()) {
            $c.win.alert("[신탁기관 계약기간] 시작일을 종료일 이전으로 선택하세요.");
            return false;
        }
    }
    // 위탁/보관기관 계약기간
    if ((txb_TRST_CUSTDN_STRT_DD.getValue() != '') && (txb_TRST_CUSTDN_END_DD.getValue() != '')) {
        if (txb_TRST_CUSTDN_STRT_DD.getValue() > txb_TRST_CUSTDN_END_DD.getValue()) {
            $c.win.alert("[위탁/보관기관 계약기간] 시작일을 종료일 이전으로 선택하세요.");
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_DUTY_HD_CMIT_YN) == "") {
        $c.win.alert("[의무보유] 확약여부를 선택해주세요");
        cmb_DUTY_HD_CMIT_YN.focus();
        return;
    }


    //의무보유 확약여부
    if ($c.stf.getObjectValue(cmb_DUTY_HD_CMIT_YN) == "Y") {
        //의무보유자
        if ($c.stf.getObjectValue(txb_DUTY_HD_NM) == "") {
            $c.win.alert("[의무보유] 의무보유자를 입력하세요.");
            txb_DUTY_HD_NM.focus();
            return;
        }
        //의무보유수량
        if (txb_DUTY_HD_CNT.getValue() == "") {
            $c.win.alert("[의무보유] 의무보유 수량을 입력하세요.");
            txb_DUTY_HD_CNT.focus();
            return;
        }
        //의무보유기간 시작일
        if (txb_DUTY_HD_STRT_DD.getValue() == "") {
            $c.win.alert("[의무보유기간] 시작일을 입력하세요.");
            txb_DUTY_HD_STRT_DD.focus();
            return;
        }
        //의무보유기간 종료일
        if (txb_DUTY_HD_END_DD.getValue() == "") {
            $c.win.alert("[의무보유기간] 종료일을 입력하세요.");
            txb_DUTY_HD_END_DD.focus();
            return;
        }
        if ((txb_DUTY_HD_STRT_DD.getValue() != '') && (txb_DUTY_HD_END_DD.getValue() != '')) {
            if (txb_DUTY_HD_STRT_DD.getValue() > txb_DUTY_HD_END_DD.getValue()) {
                $c.win.alert("[의무보유기간] 시작일을 종료일 이전으로 선택하세요.");
                return false;
            }
        }
        //의무보유해제일
        if (txb_DUTY_HD_RELEAS_DD.getValue() == "") {
            $c.win.alert("[의무보유] 해제일을 입력하세요.");
            txb_DUTY_HD_RELEAS_DD.focus();
            return;
        }
    }

    //유동성공급자계약체결여부		   
    if ($c.stf.getObjectValue(cmb_LP_CONTRT_TRD_YN) == "") {
        $c.win.alert("[유동성공급자계약] 체결여부를 선택하세요");
        cmb_LP_CONTRT_TRD_YN.focus();
        return;
    }
    //유동성공급자계약체결여부 Y일 경우 '공급자' 한명이라도 입력되어야한다.
    if ($c.stf.getObjectValue(cmb_LP_CONTRT_TRD_YN) == "Y") {
        if (($c.stf.getObjectValue(cmb_LP_MBR_NO1) == "") &&
            ($c.stf.getObjectValue(cmb_LP_MBR_NO2) == "") &&
            ($c.stf.getObjectValue(cmb_LP_MBR_NO3) == "")) {
            $c.win.alert("[유동성공급자계약] 유동성공급자를 입력하세요.");
            return;
        }
        if (($c.stf.getObjectValue(cmb_LP_MBR_NO1) == "") &&
            (($c.stf.getObjectValue(cmb_LP_MBR_NO2) != "") ||
                ($c.stf.getObjectValue(cmb_LP_MBR_NO3) == ""))) {
            $c.win.alert("[유동성공급자계약] 유동성공급자를 순서대로 입력하세요.");
            return;
        } else if ((($c.stf.getObjectValue(cmb_LP_MBR_NO2) == "") || ($c.stf.getObjectValue(cmb_LP_MBR_NO1) == "")) &&
            ($c.stf.getObjectValue(cmb_LP_MBR_NO3) != "")) {
            $c.win.alert("[유동성공급자계약] 유동성공급자를 순서대로 입력하세요.");
            return;
        }
    }



    //유동성공급자1 값이 있으면 시작기간 필수
    if (($c.stf.getObjectValue(cmb_LP_MBR_NO1) != "") && (txb_LP_CONTRT_STRT_DD.getValue() == "")) {
        $c.win.alert("[유동성공급자I] 계약기간 시작일을 입력하세요.");
        txb_LP_CONTRT_STRT_DD.focus();
        return;
    }
    if (((txb_LP_CONTRT_STRT_DD.getValue() != "") || (txb_LP_CONTRT_END_DD.getValue() != '')) && ($c.stf.getObjectValue(cmb_LP_MBR_NO1) == "")) {
        $c.win.alert("[유동성공급자I] 공급자를 선택하세요.");
        cmb_LP_MBR_NO1.focus();
        return;
    }
    if ((txb_LP_CONTRT_STRT_DD.getValue() != '') && (txb_LP_CONTRT_END_DD.getValue() != '')) {
        if (txb_LP_CONTRT_STRT_DD.getValue() > txb_LP_CONTRT_END_DD.getValue()) {
            $c.win.alert("[유동성공급자I] 계약기간 시작일을 종료일 이전으로 선택하세요.");
            return false;
        }
    }

    //유동성공급자2 값이 있으면 시작기간 필수
    if (($c.stf.getObjectValue(cmb_LP_MBR_NO2) != "") && (txb_LP_CONTRT_STRT_DD2.getValue() == "")) {
        $c.win.alert("[유동성공급자II] 계약기간 시작일을 입력하세요.");
        txb_LP_CONTRT_STRT_DD2.focus();
        return;
    }
    if (((txb_LP_CONTRT_STRT_DD2.getValue() != "") || (txb_LP_CONTRT_END_DD2.getValue() != '')) && ($c.stf.getObjectValue(cmb_LP_MBR_NO2) == "")) {
        $c.win.alert("[유동성공급자II] 공급자를 선택하세요.");
        cmb_LP_MBR_NO2.focus();
        return;
    }
    if ((txb_LP_CONTRT_STRT_DD2.getValue() != '') && (txb_LP_CONTRT_END_DD2.getValue() != '')) {
        if (txb_LP_CONTRT_STRT_DD2.getValue() > txb_LP_CONTRT_END_DD2.getValue()) {
            $c.win.alert("[유동성공급자II] 계약기간 시작일을 종료일 이전으로 선택하세요.");
            return false;
        }
    }

    //유동성공급자3 값이 있으면 시작기간 필수
    if (($c.stf.getObjectValue(cmb_LP_MBR_NO3) != "") && (txb_LP_CONTRT_STRT_DD3.getValue() == "")) {
        $c.win.alert("[유동성공급자III] 계약기간 시작일을 입력하세요.");
        txb_LP_CONTRT_STRT_DD3.focus();
        return;
    }
    if (((txb_LP_CONTRT_STRT_DD3.getValue() != "") || (txb_LP_CONTRT_END_DD3.getValue() != '')) && ($c.stf.getObjectValue(cmb_LP_MBR_NO3) == "")) {
        $c.win.alert("[유동성공급자III] 공급자를 선택하세요.");
        cmb_LP_MBR_NO3.focus();
        return;
    }
    if ((txb_LP_CONTRT_STRT_DD3.getValue() != '') && (txb_LP_CONTRT_END_DD3.getValue() != '')) {
        if (txb_LP_CONTRT_STRT_DD3.getValue() > txb_LP_CONTRT_END_DD3.getValue()) {
            $c.win.alert("[유동성공급자III] 계약기간 시작일을 종료일 이전으로 선택하세요.");
            return false;
        }
    }

    //만기유무
    /*if(mr_BAS_EXP_YN.CodeValue == ""){
    	alert("[만기 유무] YES/NO 선택하세요." );
    	mr_BAS_EXP_YN.focus();
    	return;
    }	*/

    if (mr_BAS_EXP_YN.getValue() == "Y") {
        if (txb_LSTTRD_DD.getValue() == "") {
            $c.win.alert("[만기/중도상환에 관한 사항] 최종거래일을 입력하세요.");
            txb_LSTTRD_DD.focus();
            return;
        }
    }
    // 증권의 조기청산 가능여부	
    if (mr_EARY_CLR_YN.getValue() == "") {
        $c.win.alert("[증권의 조기청산 가능 여부] YES/NO 선택하세요.");
        mr_EARY_CLR_YN.focus();
        return;
    }
    //상장여부	
    /*if(mr_LIST_APPLNT_LIST_YN.CodeValue == ""){
    	alert("[상장 여부] YES/NO 선택하세요." );
    	mr_LIST_APPLNT_LIST_YN.focus();
    	return;
    }*/
    //주식회사 여부			
    if (mr_LIST_APPLNT_COLTD_YN.getValue() == "") {
        $c.win.alert("[주식회사 여부] YES/NO 선택하세요.");
        mr_LIST_APPLNT_COLTD_YN.focus();
        return;
    }
    //상장신청인 담당자명
    if ($c.stf.getObjectValue(txb_LIST_APPL_CHRG_NM) == "") {
        $c.win.alert("[상장신청인] 담당자명을 입력해주세요.");
        txb_LIST_APPL_CHRG_NM.focus();
        return;
    }
    //상장신청인 담당자 연락처
    if ($c.stf.getObjectValue(txb_LIST_APPL_CHRG_TEL_NO) == "") {
        $c.win.alert("[상장신청인] 담당자 연락처를 입력해주세요.");
        txb_LIST_APPL_CHRG_TEL_NO.focus();
        return;
    }

    // 분배금 지급일 체크
    if (scwin.fn_Check_DISTR_PAY() == false) {
        return;
    }

    // 길이체크
    if (!$c.stf.checkMaxLength(txb_DIGITAL_SECU_ULY_NM, 200, "기초자산")) return false;
    if (!$c.stf.checkMaxLength(txb_TRST_INST_ISUR_NM, 200, "신탁기관명")) return false;
    if (!$c.stf.checkMaxLength(txb_TRST_CUSTDN_NM, 200, "위탁/보관기관")) return false;
    if (!$c.stf.checkMaxLength(txb_BENF_NMLIST_ADM_AGNT_NM, 200, "수익자명부관리 대행기관")) return false;
    if (!$c.stf.checkMaxLength(txb_DUTY_HD_NM, 100, "의무보유자")) return false;
    if (!$c.stf.checkMaxLength(txb_LIST_APPL_CHRG_NM, 100, "상장신청인 담당자")) return false;
    if (!$c.stf.checkMaxLength(txb_LIST_APPL_CHRG_TEL_NO, 40, "상장신청인 담당자 연락처")) return false;
    if (!$c.stf.checkMaxLength(txb_TRST_INST_CHRG_NM, 100, "신탁기관 담당자")) return false;
    if (!$c.stf.checkMaxLength(txb_TRST_INST_CHRG_TEL_NO, 40, "신탁기관 담당자 연락처")) return false;
    if (!$c.stf.checkMaxLength(txb_DESIGN_ADVSER_CHRG_NM, 100, "지정자문인 담당자")) return false;
    if (!$c.stf.checkMaxLength(txb_DESIGN_ADVSER_CHRG_TEL_NO, 40, "지정자문인 담당자 연락처")) return false;
    return true;
};


/********************************************** 
 * 함수명 : fn_Check_DISTR_PAY() 
 * 설명    : 분배금 지급 기준일 필수값 체크
 ***********************************************/
scwin.fn_Check_DISTR_PAY = function() {
    var vCheck = false;
    var componuntName;
    var componuntValue;

    // 분배금형태가 지급이라면
    // 기준일 입력을 확인한다.
    if ($c.stf.getObjectValue(cmb_DIGITAL_SECU_DISTR_TP_CD) == '02') {
        for (var i = 12; i >= 1; i--) {
            componuntName = "cmb_DISTR_PAY_BAS_M" + i;
            componuntValue = $c.stf.getObjectValue(document.getElementById(componuntName));
            if (componuntValue != "") {
                vCheck = true;
                break;
            }
            if (vCheck == true) {
                break;
            }
        }
        if (vCheck == false) {
            $c.win.alert("[분배금지급] 지급 기준일을 입력하세요.");
            return false;
        }
    }
    var vMonthId, vDayId;

    // 월+일  값 유효성 체크
    for (var i = 1; i <= 12; i++) {
        vMonthId = "cmb_DISTR_PAY_BAS_M" + i;
        vDayId = "cmb_DISTR_PAY_BAS_D" + i;
        if (($c.stf.getObjectValue(document.getElementById(vMonthId)) != "") && ($c.stf.getObjectValue(document.getElementById(vDayId)) == "")) {
            $c.win.alert("[분배금지급 지급기준일" + i + "] 일자를 선택해주세요.");
            document.getElementById(vDayId).focus();
            return false;
        } else if (($c.stf.getObjectValue(document.getElementById(vDayId)) != "") && ($c.stf.getObjectValue(document.getElementById(vMonthId)) == "")) {
            $c.win.alert("[분배금지급 지급기준일" + i + "] 월을 선택해주세요.");
            document.getElementById(vMonthId).focus();
            return false;
        }
    }

    // 중간입력 체크
    // 중간의 값이 하나라도 빌 경우
    // return false; 처리
    vCheck = true;
    //var componuntName;
    //var componuntValue;

    for (var i = 12; i >= 1; i--) {
        componuntName = "cmb_DISTR_PAY_BAS_M" + i;
        componuntValue = $c.stf.getObjectValue(document.getElementById(componuntName));
        if (componuntValue != "") {
            for (var j = i--; j >= 1; j--) {
                // 빈값이 있다면
                if ($c.stf.getObjectValue(document.getElementById("cmb_DISTR_PAY_BAS_M" + j)) == "") {
                    vCheck = false;
                    break;
                }
            }
        }
        if (vCheck == false) {
            break;
        }
    }
    if (vCheck == false) {
        $c.win.alert("[분배금지급] 기준일을 순서대로 선택해주세요.");
        return false;
    }
    /*
    	for(var i = 12; i >=1; i--){

    		componuntName = "txb_DISTR_PAY_BAS_DD"+i;
    		componuntValue = getObjectValue(document.getElementById(componuntName));
    		if (componuntValue != ""){

    			for(var j = --i ; j>=1; j--){
    				// 빈값이 있다면
    				if (getObjectValue(document.getElementById("txb_DISTR_PAY_BAS_DD"+j)) == componuntValue){
    					vCheck = false;	
    					break;
    				}
    			}
    		}
    		if(vCheck == false){
    			break;
    		}
    	}

    	if (vCheck == false){
    		alert("[분배금지급] 기준일이 중복으로 선택되었습니다.");
    		return false;
    	}
    */
    return true;
};


/********************************************** 
 * 함수명 : fn_GetParIsur(arrPar) ,fn_SetParIsur(arrPar)
 * 설명    : 상장신청 발행기관 호출관련
 ***********************************************/
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_SearchIsuCd); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_SearchIsuNm); // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_SearchIsuCd.setValue(arrPar[0].ISU_CD);
        txb_SearchIsuNm.setValue(arrPar[0].ISU_KOR_NM);
    }
    scwin.fn_getBaseInfo_read_sync(); //상장원부 상세조회

};


/********************************************** 
 * 함수명 : fn_getBaseInfo_read_sync()
 * 설명    : 상장원부정보 조회
 ***********************************************/
scwin.fn_getBaseInfo_read_sync = function() {
    //상장원부정보 조회
    var url = "/digital/DigitalListinvstg.do?method=readIsuBook";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_ISU_CD=" + $c.stf.getObjectValue(txb_SearchIsuCd);
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();

    // 분배금기준일 셋팅
    scwin.fn_DISTR_Combo();
};



/********************************************** 
 * 함수명 : fn_update()
 * 설명    : update 요청
 ***********************************************/
scwin.fn_update = function() {
    if (scwin.fn_CheckForm()) {
        if ($c.cp.isModified(dts_Isu) == false) {
            $c.win.alert("수정내역이 존재하지 않습니다.");
            return;
        }
        scwin.TR_JOB = "U";
        if (!confirm('수정요청 하시겠습니까?') == true) {
            return;
        }
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
            return;
        }
        if ($c.cp.isModified(dts_Isu) == false) {
            $c.win.alert("수정 요청내역이 존재하지 않습니다.");
            return;
        }
        trs_Save.Action = $c.lcd.fn_encodeNSession("/digital/DigitalListinvstg.do?method=updateDigitalIsueBook&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01);
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.Parameters = "TRS_IDX=" + TR_JOB_INSERT + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISU_CD=" + $c.stf.getObjectValue(txb_SearchIsuCd) + ",ISUR_CD=" + $c.stf.getObjectValue(txb_LIST_APPLNT_ISUR_CD) + ",ACPT_NO=" + js_emp_no + ",LD_MKT_TP_CD=1" + ",TRANSTR_EMP_NO=" + js_emp_no;
        trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
        trs_Save.Post();
    }
};





/**
 * 신탁(위탁)회사
 */


