/**
 * LP목록 조회 시 콤보 내용 목록 조회
 */
scwin.fn_searchLPCode = function() {
    dts_LP.DataID = "/listingCommon.do?method=listLeadCom";
    dts_LP.Reset();
    dts_LP.insertRow();
    var strCbd = "",
        j;
    strCbd = (strCbd == "" ? "" : ",") + "" + "^" + "선택";
    for (j = 1; j <= dts_LP.getTotalRow(); j++) {
        strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_LP.getCellData(j, "VALUE") + "^" + dts_LP.getCellData(j, "TEXT");
    }
    cmb_LP_MBR_NO1.CBData = strCbd; // 유동성1
    cmb_LP_MBR_NO2.CBData = strCbd; // 유동성2
    cmb_LP_MBR_NO3.CBData = strCbd; // 유동성3

};



/**
  * 분배금지급
  vType : 1 : 월 2: 일
  vNumber : 기준일 
  콤보박스로 선택받은 값을 textbox에 동기화시킨다.(textbox 가 ds 와 연결되어있음)
   */
scwin.fn_DISTR = function(vType, vNumber) {
    var vDate = $c.stf.getObjectValue(document.getElementById("txb_DISTR_PAY_BAS_DD" + vNumber)); // 월+일자
    var vMonth = $c.stf.getObjectValue(document.getElementById("cmb_DISTR_PAY_BAS_M" + vNumber)); // 월
    var vDay = $c.stf.getObjectValue(document.getElementById("cmb_DISTR_PAY_BAS_D" + vNumber)); // 일


    if (vDate == "") {
        vDate = "0000";
    }
    if (vMonth == "") {
        vMonth = "00";
    }
    if (vDay == "") {
        vDay = "00";
    }
    if ((vMonth == "00") && (vDay == "00")) {
        // 값이 없을 경우 공백값으로 셋팅
        $c.stf.setObjectValue(document.getElementById("txb_DISTR_PAY_BAS_DD" + vNumber), "");
    } else {
        // 값이 있을 경우
        //값을 textbox로 셋팅하여 해당 textbox에 넣어준다.
        var str = "";
        if (vType == 1) {
            str = vMonth + vDate.substring(2, 4);
        } else {
            str = vDate.substring(0, 2) + vDay;
        }
        $c.stf.setObjectValue(document.getElementById("txb_DISTR_PAY_BAS_DD" + vNumber), str);
    }
};



/**
  * 분배금지급
   ds로 불러온 값을 콤보박스로 setting
   */
scwin.fn_DISTR_Combo = function() {
    var vDate;
    for (var i = 1; i <= 12; i++) {
        vDate = $c.stf.getObjectValue(document.getElementById("txb_DISTR_PAY_BAS_DD" + i));
        if (vDate != "") {
            $c.stf.setObjectValue(document.getElementById("cmb_DISTR_PAY_BAS_M" + i), vDate.substring(0, 2));
            $c.stf.setObjectValue(document.getElementById("cmb_DISTR_PAY_BAS_D" + i), vDate.substring(2, 4));
        } else {
            // 값이 없을 경우 공백값으로 셋팅
            $c.stf.setObjectValue(document.getElementById("cmb_DISTR_PAY_BAS_M" + i), "");
            $c.stf.setObjectValue(document.getElementById("cmb_DISTR_PAY_BAS_D" + i), "");
        }
    }
};
