        txb_DUTY_HD_NM.setReadOnly(true);
        txb_DUTY_HD_CNT.setReadOnly(true);
        txb_DUTY_HD_STRT_DD.setReadOnly(true);
        txb_DUTY_HD_END_DD.setReadOnly(true);
        txb_DUTY_HD_RELEAS_DD.setReadOnly(true);
        txb_DUTY_HD_NM.style.backgroundColor = '#b9d4f7';
        img_DUTY_HD_STRT_DD.setDisabled(true);
        img_DUTY_HD_END_DD.setDisabled(true);
        img_DUTY_HD_RELEAS_DD.setDisabled(true);
        img_DUTY_HD_STRT_DD.src = "../img/icn_calendar_d.gif";
        img_DUTY_HD_END_DD.src = "../img/icn_calendar_d.gif";
        img_DUTY_HD_RELEAS_DD.src = "../img/icn_calendar_d.gif";
        $c.stf.setObjectValue(txb_DUTY_HD_NM, "");
        txb_DUTY_HD_CNT.setValue("");
        txb_DUTY_HD_STRT_DD.setValue("");
        txb_DUTY_HD_END_DD.setValue("");
        txb_DUTY_HD_RELEAS_DD.setValue("");
    }
};
