scwin.cmb_DIGITAL_SECU_DISTR_TP_CD_OnSelChange = function() {
    // 분배금지급 기준일 활성화 처리
    var vDigitalDistrTp = false;
    // 분배금 형태가 지급일 경우 
    if ($c.stf.getObjectValue(cmb_DIGITAL_SECU_DISTR_TP_CD) == '02') {
        vDigitalDistrTp = true;
    }

    // 분배금 형태 가 미지급이거나 값이 없을  경우 기준일 1~12 비활성화
    // 분배금 형태가 지급일 경우 기준일 1~12 활성화		
    for (var i = 1; i <= 12; i++) {
        getElementById('cmb_DISTR_PAY_BAS_M' + i).setDisabled(true);
        getElementById('cmb_DISTR_PAY_BAS_D' + i).setDisabled(true);

        // 미지급이라면 이전 값 없애기
        if (vDigitalDistrTp == false) {
            $c.stf.setObjectValue(getElementById('cmb_DISTR_PAY_BAS_M' + i), "");
            $c.stf.setObjectValue(getElementById('cmb_DISTR_PAY_BAS_D' + i), "");
        }
    }
};
